<?php
$fields = match($type) {
'products'=>[['name','Product name','text',true],['summary','Short description','textarea',false],['benefits','Features & benefits','editor',false],['applications','Applications','editor',false]],
'categories'=>[['name','Category name','text',true],['description','Description','textarea',false]],
'slides'=>[['title','Slide title','text',true],['description','Description','textarea',false],['button_text','Button label','text',false],['button_url','Button URL','text',true]],
'company_sections'=>[['title','Section title','text',true],['description','Company information','editor',false]],
'contacts'=>[['title','Location / department','text',true],['email','Email address','email',false],['phone','Phone number','text',false],['address','Address','textarea',false],['hours','Opening hours','text',false]],
}; ?>
<form method="post" enctype="multipart/form-data" action="<?= url('admin/'.$type.'/save') ?>" class="panel crud-form"><?= csrf_field() ?><input type="hidden" name="id" value="<?= e($row['id']??'') ?>"><div class="panel-heading"><div><span class="eyebrow">CONTENT DETAILS</span><h2><?= empty($row)?'Create a record':'Edit record #'.$row['id'] ?></h2></div><a class="btn" href="<?= url('admin/'.$type) ?>">← Back to list</a></div><div class="form-grid"><?php foreach($fields as [$key,$label,$kind,$required]): ?><?php $wide=in_array($kind,['textarea','editor']); $default=$key==='button_url'?'/products':'';$max=$key==='phone'?100:($key==='hours'?255:190);$help=$key==='button_url'?'Use /products, /company, /contact or a full https:// URL.':null; require BASE_PATH.'/app/Views/partials/admin-field.php'; ?><?php endforeach; ?><?php if($type==='products'): ?><div class="field"><label for="category_id">Product category *</label><select name="category_id" id="category_id" required><option value="">Select category</option><?php foreach($categories as $c): ?><option value="<?= $c['id'] ?>" <?= field_value($row,'category_id')==$c['id']?'selected':'' ?>><?= e($c['name']) ?></option><?php endforeach; ?></select><?php if(!$categories): ?><small>Create a category before adding a product. <a href="<?= url('admin/categories/create') ?>">Add category ↗</a></small><?php endif; ?></div><?php else: ?><?php $key='sort_order';$label='Display order';$kind='number';$default=0;$wide=false;$required=true;$help='Lower numbers appear first.';$max=null;require BASE_PATH.'/app/Views/partials/admin-field.php'; ?><?php endif; ?><?php $uploads=$type==='products'?['image'=>['Product image','image'],'data_sheet'=>['Product Data Sheet','pdf'],'safety_sheet'=>['Safety Data Sheet','pdf']]:(in_array($type,['slides','company_sections'])?['image'=>['Image','image']]:[]); foreach($uploads as $key=>[$label,$kind]) require BASE_PATH.'/app/Views/partials/admin-upload.php'; ?><?php if($type!=='categories'): ?><div class="field full checkbox-row"><label class="checkbox"><input type="checkbox" name="published" <?= field_value($row,'published',0)?'checked':'' ?>> Published on website</label><?php if($type==='products'): ?><label class="checkbox"><input type="checkbox" name="featured" <?= field_value($row,'featured',0)?'checked':'' ?>> Featured on homepage</label><?php endif; ?></div><?php endif; ?></div><div class="form-actions"><a class="btn" href="<?= url('admin/'.$type) ?>">Cancel</a><button class="btn btn-primary">Save changes</button></div></form>
